mapper.update:
update cbs.t_role
set role_name = #{r.role_name},
    data_scope = #{r.data_scope},
    perms = #{r.perms, typeHandler=org.apache.ibatis.type.ArrayTypeHandler}
where role_code = #{r.role_code}
